import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"部署说明","description":"","frontmatter":{},"headers":[],"relativePath":"projects/music-hud-paper/docs/deployment.md","filePath":"projects/music-hud-paper/docs/deployment.md"}'),n={name:"projects/music-hud-paper/docs/deployment.md"};function i(d,e,c,s,u,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="部署说明" tabindex="-1">部署说明 <a class="header-anchor" href="#部署说明" aria-label="Permalink to &quot;部署说明&quot;">​</a></h1><table tabindex="0"><thead><tr><th>使用方式</th><th>安装位置</th></tr></thead><tbody><tr><td>单人游戏</td><td>客户端安装对应 Minecraft 版本和加载器的模组</td></tr><tr><td>独立 Fabric / NeoForge 模组服</td><td>客户端和服务器均安装匹配的模组；Fabric 服务器还需要 Fabric API</td></tr><tr><td>独立 Paper 服务器</td><td>客户端安装模组，Paper 服务器安装 Paper 插件</td></tr><tr><td>Velocity 群组服</td><td>客户端安装模组，只在 Velocity 代理安装 Velocity 插件</td></tr><tr><td>BungeeCord 群组服</td><td>客户端安装模组，只在 BungeeCord 代理安装 BungeeCord 插件</td></tr></tbody></table><p><strong>群组服的所有后端均不要安装本项目的插件或服务端模组，禁止代理端与后端双装。</strong> 公共播放状态、队列和管理命令由代理持有；切换后端仍由同一代理协调播放。</p><p>Paper 会检查实际生效的代理转发配置并拒绝错误部署。Paper 插件及 Fabric / NeoForge 专用服模组会回应代理的存在性探测；客户端模组和单人内置服务器不回应此探测。代理会在进入后端和切服时检测冲突；发现双装后会提示并断开受影响的连接。请从所有后端移除本项目的插件或服务端模组，按服务器正常维护流程重新启动并连接。此检测不负责扫描离线后端，也不提供任意插件热重载支持。</p><p>公共播放协议现为 <code>3.0.0-alpha</code>，完整保留共享时间线的纳秒精度。升级时须同时更新客户端及负责公共播放的服务器模组或代理插件；旧 <code>2.x</code> 协议端会在握手时被拒绝。</p><h2 id="客户端" tabindex="-1">客户端 <a class="header-anchor" href="#客户端" aria-label="Permalink to &quot;客户端&quot;">​</a></h2><p>安装与 Minecraft 版本及 Fabric/NeoForge 匹配的 ModernUI 和 MusicHud TuneWeave 模组；Fabric 还需要 Fabric API。完整版本表和三条 ModernUI 下载路线见 <a href="./../README.html#客户端依赖">README</a>。26.2 / 26.3 配套 ModernUI 不需要 Forge Config API Port；其余表列版本的官方 ModernUI / mVUS Fabric 构建仍需要对应版本的 API Port，NeoForge 无需另装。</p><p>26.x 客户端运行需要 Java 25，1.21.x 客户端运行需要 Java 21。26.2 / 26.3 使用 <a href="https://github.com/MOPELotus/ModernUI-MC/releases" target="_blank" rel="noreferrer">MusicHud TuneWeave 配套的 ModernUI 分支</a>。</p><p>26.2 / 26.3 配套 ModernUI 当前使用 <code>3.13.0.9</code>。普通版（<code>-universal.jar</code>）与 MiSans 版（<code>-universal-misans.jar</code>）均可使用，按 Minecraft 版本和加载器选包，只安装其中一版；升级/切换时替换旧 JAR。普通版允许自定义字体，MiSans 版保留字体安装与字重设置；缺少字体时需主动下载并重启。两版首次创建各自配置时继承旧 <code>client.toml</code> 并保留原文件，详见 <a href="./../README.html#客户端依赖">README</a>。</p><p>在游戏内配置 TuneWeave。可选择自动下载，也可运行独立实例并配置地址（默认 <a href="http://127.0.0.1:7832" target="_blank" rel="noreferrer">http://127.0.0.1:7832</a>）。音乐账号、Cookie 和 token 只保留在客户端；服务器及代理不运行 TuneWeave，也不保存音乐平台凭据。</p><h2 id="服务器和代理" tabindex="-1">服务器和代理 <a class="header-anchor" href="#服务器和代理" aria-label="Permalink to &quot;服务器和代理&quot;">​</a></h2><p>独立 Fabric / NeoForge 模组服使用与服务端 Minecraft 版本及加载器匹配的模组 JAR，放入 <code>mods</code> 目录。客户端仍按上面的依赖说明安装。专用服务器不安装 ModernUI、不启动 TuneWeave，也不配置音乐账号；它只协调客户端解析的公共播放会话。此方式与独立 Paper 插件服并列，不在同一服务端混装模组和插件。</p><p>从 plugin 分支构建与平台对应的 Paper、Velocity 或 BungeeCord JAR，放入对应平台的 plugins 目录。使用不含 -plain 或 -sources 后缀的部署 JAR。插件字节码目标为 Java 21；实际运行 Java 版本还须满足所用服务器或代理自身要求。</p><p>客户端和插件应使用相互匹配的 MusicHud TuneWeave 版本。项目命名空间为 musichud_tuneweave，与上游 MusicHud 不兼容，不能同时安装。配置和 Uni 数据使用本项目独立目录，不自动迁移上游旧数据。</p><h3 id="curseforge-client-edition" tabindex="-1">CurseForge client edition <a class="header-anchor" href="#curseforge-client-edition" aria-label="Permalink to &quot;CurseForge client edition&quot;">​</a></h3><p>The CF client only connects to a TuneWeave service installed and started outside the mod. It has no executable configuration, acquisition, automatic startup, child-process management or process-log controls. Enter the running service address in the client settings. CF connection preferences use <code>musichud_tuneweave-cf-server.toml</code>; switching editions preserves the standard edition’s local-process configuration. The first-use notice and version notifications link only to the <a href="https://github.com/MOPELotus/MusicHud-TuneWeave" target="_blank" rel="noreferrer">project homepage</a>. The standard edition retains its complete TuneWeave management features.</p>',16)])])}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
